#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
struct RateOwnershipDump {static void dump(const Graph&g){for(size_t i=0;i<g.elements.size();++i){bool relevant=i==2230||i==2232||i==2237;for(auto&a:g.elements[i].attributes)if(a.type==1||a.type==15)for(auto&v:a.values)if(v.reference==2230||v.reference==2232||v.reference==2237)relevant=true;if(!relevant)continue;std::cout<<"owner_element="<<i<<" type="<<g.strings[g.elements[i].type]<<'\n';for(auto&a:g.elements[i].attributes){std::cout<<" field="<<g.strings[a.name]<<" kind="<<unsigned(a.type);if(a.type==1||a.type==15)for(auto&v:a.values)std::cout<<" ref="<<v.reference;std::cout<<'\n';}}}};
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("session path required");auto g=loadGraph(argv[1]);RateOwnershipDump::dump(g);for(size_t i=0;i<g.elements.size();++i)for(auto&a:g.elements[i].attributes){auto name=g.strings[a.name];auto lower=name;for(auto&c:lower)c=char(std::tolower(static_cast<unsigned char>(c)));if(lower.find("rate")==std::string::npos&&lower.find("fps")==std::string::npos)continue;std::cout<<"element="<<i<<" type="<<g.strings[g.elements[i].type]<<" attribute="<<name<<" wire_type="<<unsigned(a.type)<<" count="<<a.values.size();for(auto&v:a.values){if(a.type==3)std::cout<<" float="<<wireFloat(v);if(a.type==2)std::cout<<" int="<<wireInt(v);if(a.type==1)std::cout<<" reference="<<v.reference;}std::cout<<'\n';}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
